import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function based on weighted sum of absolute values, a quadratic component with interaction, and a smoothed hinge loss function for introducing skewness and non-linearity.

    Formula:
    f(x) = 0.3 * np.sum(np.abs(x)) + 0.7 * (x[0]**2 + x[1]**2 + 0.5 * x[0] * x[1]) + smoothed_hinge_loss(x[0])

    where:
    smoothed_hinge_loss(z) = 0, if z > 1; 0.5 * (1 - z)**2, if 0 <= z <= 1; -z + 0.5 if z <0
    """

    def smoothed_hinge_loss(z):
          if z > 1:
                return 0
          elif z >= 0 and z <= 1:
                return 0.5 * (1 - z)**2
          else:
                return -z + 0.5

    return 0.3 * np.sum(np.abs(x)) + 0.7 * (x[0]**2 + x[1]**2 + 0.5 * x[0] * x[1]) + smoothed_hinge_loss(x[0])

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a rational skew function, a polynomial, and a complex interaction term.

    Formula:
    f(x) = scale(x[0]) * (x[0]**3 + x[1]**3 + x[0] * x[1]**2 + x[0]**2 * x[1]) + interaction(x)

    where:
    scale(z) = (z + 5) / 10  # Rational function scaling to [0, 1] when x[0] is in [-5, 5]
    interaction(x) = 0.1 * (x[0] * np.sin(x[1]) + x[1] * np.cos(x[0]))
    """

    def scale(z):
        return (z + 5) / 10

    def interaction(x):
        return 0.1 * (x[0] * np.sin(x[1]) + x[1] * np.cos(x[0]))

    return scale(x[0]) * (x[0]**3 + x[1]**3 + x[0] * x[1]**2 + x[0]**2 * x[1]) + interaction(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining polynomial and rational terms, modulated by a sigmoid and a Gaussian function. This aims for a landscape with valleys, skewness, and moderate ruggedness.

    Formula:
    f(x) = scale * (sigmoid(x[0]) * (x[0]**2 + x[1]**2) + gaussian(x[0], x[1]) * (x[0]**4 + x[1]**2) / (1 + 0.1 * (x[0]**2 + x[1]**2)) + interaction)

    where:
    sigmoid(z) = 1 / (1 + exp(-z))
    gaussian(x, y) = exp(-(x**2 + y**2)/2)  # centered at (0,0), variance = 1
    interaction = 0.2 * x[0] * x[1]
    scale = 0.4
    """
    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    def gaussian(x, y):
        return np.exp(-(x**2 + y**2)/2)

    scale = 0.4
    interaction = 0.2 * x[0] * x[1]

    return scale * (sigmoid(x[0]) * (x[0]**2 + x[1]**2) + gaussian(x[0], x[1]) * (x[0]**4 + x[1]**2) / (1 + 0.1 * (x[0]**2 + x[1]**2)) + interaction)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining polynomial components with a scaled sigmoid function for skewness and regularization, plus a product term for interaction and sinusoidal modulating terms.

    Formula:
    f(x) =  0.01 * (0.2 * sigmoid(4 * x[0] + 2) * (x[0]**2 + x[1]**2 + 0.2 * x[0] * x[1]) + 0.1 * np.prod(x) + 0.01 * x[1]**3 + 0.02 * np.sin(3 * x[0]) + 0.02 * np.cos(3*x[1]))

    where:
    sigmoid(z) = 1 / (1 + exp(-z))
    """
    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    return 0.01 * (0.2 * sigmoid(4 * x[0] + 2) * (x[0]**2 + x[1]**2 + 0.2 * x[0] * x[1]) + 0.1 * np.prod(x) + 0.01 * x[1]**3 + 0.02 * np.sin(3 * x[0]) + 0.02 * np.cos(3*x[1]))
